    cp.read(cnf)
    c = cp['client']
    return dict(host=c['host'], port=int(c['port']), user=c['user'], password=c.get('password','').strip('"'), database=c.get('database','ads'), charset='utf8mb4', connect_timeout=8, read_timeout=30)

